const PROJECT='TRIP1', OK=200, LOGIC=1600, DATA=1301, ADMIN=2401;
const json = (value,fallback) => { try{return JSON.parse(value)}catch{return fallback} };
const id = () => crypto.randomUUID().replaceAll('-','');
const now = () => Math.floor(Date.now()/1000);
const pageInput=p=>({page:Math.max(1,Number(p.page)||1),size:Math.min(50,Math.max(1,Number(p.size)||20))});
const response=(data={},code=OK,msg='ok')=>({code,msg,data});
class ApiError extends Error { constructor(message,code=LOGIC){super(message);this.code=code;} }
const must=(value,name)=>{if(value===undefined||value===null||String(value).trim()==='')throw new ApiError(`请填写${name}`,DATA);return value};

function callStatement(method,sql,params) {
  const statement=db.prepare(sql);
  return Array.isArray(params)?statement[method](...params):statement[method](params||{});
}
function run(sql,params={}) { return callStatement('run',sql,params); }
function one(sql,params={}) { return callStatement('get',sql,params); }
function all(sql,params={}) { return callStatement('all',sql,params); }
function paginate(table,where,params,order,page,size) {
  const total=Number(one(`SELECT count(*) total FROM ${table} WHERE ${where}`,params).total);
  return {page,size,total,list:all(`SELECT * FROM ${table} WHERE ${where} ORDER BY ${order} LIMIT $size OFFSET $offset`,{...params,$size:size,$offset:(page-1)*size})};
}
function contentRow(kind,row,detail=false) {
  if(!row)return null;const p=kind.toUpperCase()+'_';
  if(kind==='spot')return {_id:row.id,[p+'TITLE']:row.title,[p+'CATE_ID']:row.category_id,[p+'CATE_NAME']:row.category_name,[p+'OBJ']:json(row.data_json,{}),[p+'FORMS']:json(row.forms_json,[]),[p+'STATUS']:row.status,[p+'CMS_STATE']:row.cms_state,[p+'ORDER']:row.sort_order,[p+'VOUCH']:row.featured,[p+'VIEW_CNT']:row.view_count,[p+'DEMO']:!!row.is_demo,[p+'ADD_TIME']:row.created_at,[p+'PUBLISH_TIME']:row.published_at};
  if(kind==='guide')return {_id:row.id,GUIDE_TITLE:row.title,GUIDE_CATE_ID:row.category_id,GUIDE_CATE_NAME:row.category_name,GUIDE_DURATION:row.duration,GUIDE_OBJ:json(row.data_json,{}),GUIDE_FORMS:json(row.forms_json,[]),GUIDE_STATUS:row.status,GUIDE_CMS_STATE:row.cms_state,GUIDE_ORDER:row.sort_order,GUIDE_VOUCH:row.featured,GUIDE_VIEW_CNT:row.view_count,GUIDE_DEMO:!!row.is_demo,GUIDE_ADD_TIME:row.created_at,GUIDE_PUBLISH_TIME:row.published_at};
  if(kind==='news')return {_id:row.id,NEWS_TITLE:row.title,NEWS_DESC:row.description,NEWS_CATE_ID:row.category_id,NEWS_CATE_NAME:row.category_name,NEWS_PIC:json(row.pictures_json,[]),NEWS_CONTENT:detail?json(row.content_json,[]):[],NEWS_OBJ:json(row.data_json,{}),NEWS_FORMS:json(row.forms_json,[]),NEWS_STATUS:row.status,NEWS_CMS_STATE:row.cms_state,NEWS_ORDER:row.sort_order,NEWS_VOUCH:row.featured,NEWS_VIEW_CNT:row.view_count,NEWS_DEMO:!!row.is_demo,NEWS_ACTIVITY_START:row.activity_start,NEWS_ACTIVITY_END:row.activity_end,NEWS_ADD_TIME:row.created_at,NEWS_PUBLISH_TIME:row.published_at};
  if(kind==='scenic')return {_id:row.id,SCENIC_NAME:row.name,SCENIC_DESC:row.description,SCENIC_ADDRESS:row.address,SCENIC_HOURS:row.hours,SCENIC_PHONE:row.phone,SCENIC_IMAGES:json(row.images_json,[]),SCENIC_CONTENT:json(row.content_json,[]),SCENIC_INFO:json(row.info_json,{}),SCENIC_STATE:row.state,SCENIC_ORDER:row.sort_order,SCENIC_DEMO:!!row.is_demo,SCENIC_PUBLISH_TIME:row.published_at};
  if(kind==='merchant')return {_id:row.id,MERCHANT_NAME:row.name,MERCHANT_CATEGORY:row.category,MERCHANT_DESC:row.description,MERCHANT_PHONE:row.phone,MERCHANT_ADDRESS:row.address,MERCHANT_HOURS:row.hours,MERCHANT_IMAGES:json(row.images_json,[]),MERCHANT_CONTENT:json(row.content_json,[]),MERCHANT_STATE:row.state,MERCHANT_ORDER:row.sort_order,MERCHANT_DEMO:!!row.is_demo,MERCHANT_PUBLISH_TIME:row.published_at};
  if(kind==='panorama')return {_id:row.id,PANORAMA_NAME:row.name,PANORAMA_DESC:row.description,PANORAMA_COVER:json(row.cover_json,[]),PANORAMA_RESOURCE_TYPE:row.resource_type,PANORAMA_RESOURCE:row.resource,PANORAMA_CONTENT:json(row.content_json,[]),PANORAMA_STATE:row.state,PANORAMA_ORDER:row.sort_order,PANORAMA_DEMO:!!row.is_demo,PANORAMA_PUBLISH_TIME:row.published_at};
}
const modules={spot:{table:'spots',title:'title',state:'cms_state'},guide:{table:'guides',title:'title',state:'cms_state'},news:{table:'news',title:'title',state:'cms_state'},scenic:{table:'scenic',title:'name',state:'state'},panorama:{table:'panoramas',title:'name',state:'state'}};
const merchantTables={food:'food_merchants',stay:'stay_merchants',travel:'travel_merchants'};
function merchantCategory(value){const category=String(value||'');if(!merchantTables[category])throw new ApiError('商户类型必须是餐饮、住宿或交通',DATA);return category;}
function merchantRecord(recordId){const registry=one('SELECT * FROM merchant_registry WHERE id=? AND project_id=?',[recordId,PROJECT]);if(!registry)return null;const row=one(`SELECT * FROM ${merchantTables[registry.category]} WHERE id=? AND project_id=?`,[recordId,PROJECT]);return row?{...row,category:registry.category}:null;}
function publicList(kind,p={}) {
  if(kind==='merchant'){
    const category=merchantCategory(p.category),table=merchantTables[category],{page,size}=pageInput(p),args={$project:PROJECT},clauses=['project_id=$project',"state='published'",'deleted=0'];
    if(p.search){clauses.push('name LIKE $search');args.$search=`%${String(p.search).slice(0,50)}%`;}
    const result=paginate(table,clauses.join(' AND '),args,'sort_order ASC, created_at DESC',page,size);result.list=result.list.map(row=>contentRow(kind,{...row,category}));return result;
  }
  const meta=modules[kind];if(!meta)throw new ApiError('内容模块不正确',DATA);const {page,size}=pageInput(p),args={$project:PROJECT},clauses=['project_id=$project',`${meta.state}='published'`,'deleted=0'];
  if(p.search){clauses.push(`${meta.title} LIKE $search`);args.$search=`%${String(p.search).slice(0,50)}%`;}
  const category=p.category||p.cateId||(p.sortType==='cateId'?p.sortVal:'');if(category&&['spot','guide','news'].includes(kind)){clauses.push('category_id IN (SELECT id FROM content_categories WHERE project_id=$project AND module=$module AND category_key=$category)');args.$module=kind;args.$category=String(category);}
  const order=p.sortMode==='latest'?'published_at DESC':p.orderBy&&Object.keys(p.orderBy)[0]?.includes('VIEW_CNT')?'view_count DESC, created_at DESC':'sort_order ASC, created_at DESC';
  const result=paginate(meta.table,clauses.join(' AND '),args,order,page,size);result.list=result.list.map(row=>contentRow(kind,row));return result;
}
function publicDetail(kind,recordId) {
  if(kind==='merchant'){const row=merchantRecord(must(recordId,'内容编号'));if(!row||row.state!=='published'||row.deleted)throw new ApiError('内容不存在或尚未发布');return contentRow(kind,row,true);}
  const meta=modules[kind];if(!meta)throw new ApiError('内容模块不正确',DATA);const row=one(`SELECT * FROM ${meta.table} WHERE id=$id AND project_id=$project AND ${meta.state}='published' AND deleted=0`,{$id:must(recordId,'内容编号'),$project:PROJECT});if(!row)throw new ApiError('内容不存在或尚未发布');
  if(['spot','guide','news'].includes(kind))run(`UPDATE ${meta.table} SET view_count=view_count+1 WHERE id=$id`,{$id:row.id});const result=contentRow(kind,row,true);
  if(kind==='guide')result.GUIDE_SPOTS=all('SELECT s.*,gs.position,gs.duration route_duration,gs.note,gs.highlight FROM guide_spots gs JOIN spots s ON s.id=gs.spot_id WHERE gs.guide_id=$id AND s.cms_state=\'published\' AND s.deleted=0 ORDER BY gs.position',{$id:row.id}).map(s=>({_id:s.id,SPOT_TITLE:s.title,SPOT_OBJ:json(s.data_json,{}),duration:s.route_duration,note:s.note,highlight:s.highlight,cover:(json(s.data_json,{}).cover||[])[0]||''}));
  return result;
}
function userFor(token,create=true){const openid=token||'local-visitor';let row=one('SELECT * FROM users WHERE project_id=? AND mini_openid=?',[PROJECT,openid]);if(!row&&create){const uid=id();run('INSERT INTO users(id,project_id,mini_openid,name) VALUES(?,?,?,?)',[uid,PROJECT,openid,'本地游客']);row=one('SELECT * FROM users WHERE id=?',[uid]);}return row;}
function requireAdmin(token){const row=one('SELECT * FROM admins WHERE project_id=? AND token=? AND token_expires_at>? AND status=1 AND deleted=0',[PROJECT,token,now()]);if(!row)throw new ApiError('管理员登录已过期',ADMIN);return row;}
function ensureAdmin(){if(one('SELECT id FROM admins WHERE project_id=? LIMIT 1',[PROJECT]))return;const salt='wetravel-local',hash=crypto.scryptSync('123456',salt,32).toString('hex');run('INSERT INTO admins(id,project_id,name,password_hash,description,role,permissions_json) VALUES(?,?,?,?,?,?,?)',['local-admin',PROJECT,'admin',`scrypt$${salt}$${hash}`,'本地超级管理员',1,'{}']);}
ensureAdmin();

function homePortal(){const setting=one('SELECT value_json FROM settings WHERE project_id=? AND setting_key=?',[PROJECT,'SETUP_HOME_PORTAL']);const config=json(setting&&setting.value_json,{}).published;if(!config)return{configured:false,slides:[],featured:[],scenic:null};const scenic=config.scenicId?contentRow('scenic',one("SELECT * FROM scenic WHERE id=? AND state='published' AND deleted=0",[config.scenicId]),true):null;const featured=(config.featured||[]).map(ref=>{try{const row=publicDetail(ref.module,ref.id);const p=ref.module.toUpperCase()+'_';return{id:row._id,_id:row._id,type:ref.module,title:row[p+'TITLE']||row[p+'NAME'],desc:row[p+'DESC']||(row[p+'OBJ']||{}).desc||'',pic:(row[p+'PIC']||row[p+'IMAGES']||row[p+'COVER']||(row[p+'OBJ']||{}).cover||[])[0]||'',...row};}catch{return null}}).filter(Boolean);return{configured:true,brandName:config.brandName||'WeTravel',slides:config.slides||[],featured,scenic};}
function categories(module){return all("SELECT category_key id,name FROM content_categories WHERE project_id=? AND module=? AND state='published' AND deleted=0 ORDER BY sort_order",[PROJECT,module]);}
function feedbackRow(row){return{_id:row.id,FEEDBACK_CATEGORY:row.category,FEEDBACK_CONTENT:row.content,FEEDBACK_PHONE:row.phone,FEEDBACK_IMAGES:json(row.images_json,[]),FEEDBACK_IMAGE_URLS:json(row.images_json,[]),FEEDBACK_STATUS:row.status,FEEDBACK_REPLY:row.reply,FEEDBACK_REPLY_TIME:row.reply_at,FEEDBACK_PROCESS_TIME:row.processed_at,FEEDBACK_ADD_TIME:row.created_at};}
function audit(admin,content,logType=99){run('INSERT INTO admin_logs(id,project_id,admin_id,admin_name,admin_description,content,log_type) VALUES(?,?,?,?,?,?,?)',[id(),PROJECT,admin.id,admin.name,admin.description,content,logType]);}
function registerAsset({module,recordId,fileID,base64,userId=null,adminId=null}){run('INSERT INTO assets(id,project_id,module,record_id,owner_user_id,admin_id,file_path,mime_type,size_bytes) VALUES(?,?,?,?,?,?,?,?,?)',[id(),PROJECT,module,recordId,userId,adminId,fileID,fileID.endsWith('.png')?'image/png':'image/jpeg',Buffer.from(base64,'base64').length]);}
function cmsSave(kind,data,admin){
  if(kind==='category'){
    const recordId=data.id||id(),module=must(data.module,'所属模块'),key=must(data.key,'分类标识'),name=must(data.name,'分类名称');
    run(`INSERT INTO content_categories(id,project_id,module,category_key,name,state,sort_order,edit_admin_id) VALUES(?,?,?,?,?,'draft',?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,sort_order=excluded.sort_order,edit_admin_id=excluded.edit_admin_id,updated_at=unixepoch()`,[recordId,PROJECT,module,key,name,Number(data.order)||9999,admin.id]);
    return{id:recordId};
  }
  const meta=modules[kind];if(!meta&&kind!=='merchant')throw new ApiError('内容模块不正确',DATA);const recordId=data.id||id(),name=must(data.name||data.title,'名称或标题'),order=Number(data.order)||9999;
  if(['spot','guide','news'].includes(kind)){
    const category=one('SELECT * FROM content_categories WHERE project_id=? AND module=? AND category_key=? AND deleted=0',[PROJECT,kind,must(data.cateId,'分类')]);if(!category)throw new ApiError('分类不存在',DATA);
    if(kind==='spot')run(`INSERT INTO spots(id,project_id,category_id,title,category_name,forms_json,data_json,sort_order,edit_admin_id) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET category_id=excluded.category_id,title=excluded.title,category_name=excluded.category_name,forms_json=excluded.forms_json,data_json=excluded.data_json,sort_order=excluded.sort_order,edit_admin_id=excluded.edit_admin_id,revision=revision+1,updated_at=unixepoch()`,[recordId,PROJECT,category.id,name,category.name,JSON.stringify(data.forms||[]),JSON.stringify({cover:(data.images||[]).slice(0,1),gallery:data.images||[],desc:data.desc||'',address:data.address||'',time:data.hours||'',subtitle:data.subtitle||'',distance:data.distance||'',duration:data.duration||'',bestTime:data.bestTime||'',other:data.other||''}),order,admin.id]);
    if(kind==='guide'){
      run(`INSERT INTO guides(id,project_id,category_id,title,category_name,duration,forms_json,data_json,sort_order,edit_admin_id) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET category_id=excluded.category_id,title=excluded.title,category_name=excluded.category_name,duration=excluded.duration,forms_json=excluded.forms_json,data_json=excluded.data_json,sort_order=excluded.sort_order,edit_admin_id=excluded.edit_admin_id,revision=revision+1,updated_at=unixepoch()`,[recordId,PROJECT,category.id,name,category.name,data.duration||'',JSON.stringify(data.forms||[]),JSON.stringify({cover:(data.images||[]).slice(0,1),desc:data.desc||'',detail:data.content||[],spots:(data.route||[]).map(r=>r.spotId)}),order,admin.id]);
      run('DELETE FROM guide_spots WHERE guide_id=?',[recordId]);
      (data.route||[]).forEach((r,position)=>run('INSERT INTO guide_spots(guide_id,spot_id,position,duration,note,highlight) VALUES(?,?,?,?,?,?)',[recordId,must(r.spotId,'关联景点'),position,r.duration||'',r.note||'',r.highlight||'']));
    }
    if(kind==='news')run(`INSERT INTO news(id,project_id,category_id,title,description,category_name,pictures_json,content_json,forms_json,data_json,activity_start,activity_end,sort_order,edit_admin_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET category_id=excluded.category_id,title=excluded.title,description=excluded.description,category_name=excluded.category_name,pictures_json=excluded.pictures_json,content_json=excluded.content_json,forms_json=excluded.forms_json,data_json=excluded.data_json,activity_start=excluded.activity_start,activity_end=excluded.activity_end,sort_order=excluded.sort_order,edit_admin_id=excluded.edit_admin_id,revision=revision+1,updated_at=unixepoch()`,[recordId,PROJECT,category.id,name,data.desc||'',category.name,JSON.stringify(data.images||[]),JSON.stringify(data.content||[]),JSON.stringify(data.forms||[]),JSON.stringify({}),data.activityStart||'',data.activityEnd||'',order,admin.id]);
  } else if(kind==='scenic') run(`INSERT INTO scenic(id,project_id,name,description,address,hours,phone,images_json,content_json,info_json,sort_order,edit_admin_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,description=excluded.description,address=excluded.address,hours=excluded.hours,phone=excluded.phone,images_json=excluded.images_json,content_json=excluded.content_json,info_json=excluded.info_json,sort_order=excluded.sort_order,edit_admin_id=excluded.edit_admin_id,updated_at=unixepoch()`,[recordId,PROJECT,name,data.desc||'',data.address||'',data.hours||'',data.phone||'',JSON.stringify(data.images||[]),JSON.stringify(data.content||[]),JSON.stringify(data.info||{}),order,admin.id]);
  else if(kind==='merchant'){
    const category=merchantCategory(data.category),existing=one('SELECT category FROM merchant_registry WHERE id=? AND project_id=?',[recordId,PROJECT]);
    if(existing&&existing.category!==category)throw new ApiError('商户所属栏目创建后不能更改，请在正确栏目中新建记录',DATA);
    run('INSERT OR IGNORE INTO merchant_registry(id,project_id,category) VALUES(?,?,?)',[recordId,PROJECT,category]);
    run(`INSERT INTO ${merchantTables[category]}(id,project_id,name,description,phone,address,hours,images_json,content_json,sort_order,edit_admin_id) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,description=excluded.description,phone=excluded.phone,address=excluded.address,hours=excluded.hours,images_json=excluded.images_json,content_json=excluded.content_json,sort_order=excluded.sort_order,edit_admin_id=excluded.edit_admin_id,updated_at=unixepoch()`,[recordId,PROJECT,name,data.desc||'',data.phone||'',data.address||'',data.hours||'',JSON.stringify(data.images||[]),JSON.stringify(data.content||[]),order,admin.id]);
  }
  else if(kind==='panorama') run(`INSERT INTO panoramas(id,project_id,name,description,cover_json,resource_type,resource,content_json,sort_order,edit_admin_id) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,description=excluded.description,cover_json=excluded.cover_json,resource_type=excluded.resource_type,resource=excluded.resource,content_json=excluded.content_json,sort_order=excluded.sort_order,edit_admin_id=excluded.edit_admin_id,updated_at=unixepoch()`,[recordId,PROJECT,name,data.desc||'',JSON.stringify(data.cover||data.images||[]),data.resourceType||'image',data.resource||'',JSON.stringify(data.content||[]),order,admin.id]);
  return{id:recordId};
}
function saveBase64(folder,base64){if(typeof base64!=='string'||base64.length>7*1024*1024)throw new ApiError('图片为空或超过 5MB',DATA);const bytes=Buffer.from(base64,'base64');if(!bytes.length||bytes.length>5*1024*1024)throw new ApiError('图片为空或超过 5MB',DATA);const ext=bytes[0]===0x89&&bytes[1]===0x50?'png':bytes[0]===0xff&&bytes[1]===0xd8?'jpg':'';if(!ext)throw new ApiError('仅支持 PNG/JPEG 图片',DATA);const dir=path.join(root,'local/uploads',folder);fs.mkdirSync(dir,{recursive:true});const name=`${id()}.${ext}`;fs.writeFileSync(path.join(dir,name),bytes);return`http://127.0.0.1:${Number(process.env.WETRAVEL_LOCAL_PORT||process.env.PORT)||8787}/media/${folder}/${name}`;}
function mediaUrl(relative){return`http://127.0.0.1:${Number(process.env.WETRAVEL_LOCAL_PORT||process.env.PORT)||8787}/media/${relative}`;}
function saveQr(name,value){const qr=QRCode.create(String(value),{errorCorrectionLevel:'M'}),size=qr.modules.size,data=qr.modules.data,scale=8,quiet=4,view=(size+quiet*2)*scale;let cells='';for(let y=0;y<size;y++)for(let x=0;x<size;x++)if(data[y*size+x])cells+=`<rect x="${(x+quiet)*scale}" y="${(y+quiet)*scale}" width="${scale}" height="${scale}"/>`;const dir=path.join(root,'local/uploads/system');fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,name),`<svg xmlns="http://www.w3.org/2000/svg" width="${view}" height="${view}" viewBox="0 0 ${view} ${view}"><rect width="100%" height="100%" fill="white"/><g fill="black">${cells}</g></svg>`);return mediaUrl(`system/${name}`);}
function csvCell(value){const text=String(value??'').replaceAll('"','""');return`"${text}"`;}
function saveCsv(name,headers,rows){const dir=path.join(root,'local/uploads/exports');fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,name),'\ufeff'+[headers,...rows].map(row=>row.map(csvCell).join(',')).join('\n'));return mediaUrl(`exports/${name}`);}
function exportInfo(name,remove=false){const file=path.join(root,'local/uploads/exports',name);if(remove&&fs.existsSync(file))fs.unlinkSync(file);if(!fs.existsSync(file))return{url:'',time:''};return{url:mediaUrl(`exports/${name}`),time:new Date(fs.statSync(file).mtimeMs).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})};}
function reservationList(p={}){const {page,size}=pageInput(p),args={$project:PROJECT},clauses=['project_id=$project','status IN (1,9)'];if(p.typeId){clauses.push('type_id=$type');args.$type=p.typeId;}if(p.search){clauses.push('title LIKE $search');args.$search=`%${p.search}%`;}const result=paginate('reservations',clauses.join(' AND '),args,'sort_order ASC,created_at DESC',page,size);result.list=result.list.map(r=>({type:'reservation',id:r.id,title:r.title,desc:json(r.style_json,{}).desc||'',ext:'可预约',pic:json(r.style_json,{}).pic||''}));return result;}
function reservationAdminRow(row){const days=all('SELECT * FROM reservation_days WHERE reservation_id=? ORDER BY day',[row.id]).map(day=>({day:day.day,dayDesc:day.description,times:all('SELECT * FROM reservation_slots WHERE reservation_day_id=? ORDER BY starts_at',[day.id]).map(slot=>({mark:slot.mark,start:slot.starts_at,end:slot.ends_at,limit:slot.capacity??50,isLimit:slot.capacity!==null,status:slot.status,stat:{succCnt:Number(one('SELECT count(*) n FROM bookings WHERE slot_id=? AND status=1',[slot.id]).n),cancelCnt:Number(one('SELECT count(*) n FROM bookings WHERE slot_id=? AND status=10',[slot.id]).n),waitCheckCnt:0,adminCancelCnt:0}}))}));return{_id:row.id,RESERVATION_TITLE:row.title,RESERVATION_TYPE_ID:row.type_id,RESERVATION_TYPE_NAME:row.type_name,RESERVATION_CONTENT:json(row.content_json,[]),RESERVATION_STYLE_SET:json(row.style_json,{}),RESERVATION_FORM_SET:json(row.form_schema_json,[]),RESERVATION_DAYS_SET:days,RESERVATION_STATUS:row.status,RESERVATION_IS_SHOW_LIMIT:row.show_limit,RESERVATION_ORDER:row.sort_order,RESERVATION_VOUCH:row.featured,RESERVATION_QR:row.qr_file,RESERVATION_EDIT_TIME:row.updated_at,leaveDay:days.filter(d=>d.day>=new Date().toISOString().slice(0,10)).length};}
function bookingAdminRow(b){return{_id:b.id,BOOKING_RESERVATION_TITLE:b.reservation_title,BOOKING_RESERVATION_DAY:b.booking_day,BOOKING_RESERVATION_TIME_START:b.starts_at,BOOKING_RESERVATION_TIME_END:b.ends_at,BOOKING_STATUS:b.status,BOOKING_CODE:b.verification_code,BOOKING_IS_CHECKIN:b.checked_in,BOOKING_CHECKIN_TIME:b.checked_in_at,BOOKING_REASON:b.reason,BOOKING_FORMS:json(b.forms_json,[]),BOOKING_ADD_TIME:b.created_at,BOOKING_EDIT_TIME:b.updated_at};}
function saveReservation(data,admin,recordId=data.id||id()){
  const title=must(data.title,'标题'),typeId=must(data.typeId,'分类'),days=data.daysSet||[];
  run(`INSERT INTO reservations(id,project_id,admin_id,title,type_id,type_name,content_json,style_json,form_schema_json,status,show_limit,sort_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET admin_id=excluded.admin_id,title=excluded.title,type_id=excluded.type_id,type_name=excluded.type_name,form_schema_json=excluded.form_schema_json,show_limit=excluded.show_limit,sort_order=excluded.sort_order,updated_at=unixepoch()`,[recordId,PROJECT,admin.id,title,typeId,data.typeName||typeId,JSON.stringify(data.content||[]),JSON.stringify(data.styleSet||{}),JSON.stringify(data.formSet||[]),Number(data.status??1),Number(data.isShowLimit??1),Number(data.order)||9999]);
  const retained=[];
  for(const day of days){let dayRow=one('SELECT id FROM reservation_days WHERE reservation_id=? AND day=?',[recordId,day.day]);const dayId=dayRow?.id||id();if(!dayRow)run('INSERT INTO reservation_days(id,project_id,reservation_id,day,description) VALUES(?,?,?,?,?)',[dayId,PROJECT,recordId,day.day,day.dayDesc||'']);else run('UPDATE reservation_days SET description=?,updated_at=unixepoch() WHERE id=?',[day.dayDesc||'',dayId]);for(const slot of day.times||[]){retained.push(slot.mark);const old=one('SELECT s.id FROM reservation_slots s JOIN reservation_days d ON d.id=s.reservation_day_id WHERE d.project_id=? AND s.mark=?',[PROJECT,slot.mark]);const capacity=slot.isLimit===false?null:Number(slot.limit)||0;if(old)run('UPDATE reservation_slots SET reservation_day_id=?,starts_at=?,ends_at=?,capacity=?,status=?,updated_at=unixepoch() WHERE id=?',[dayId,slot.start,slot.end,capacity,Number(slot.status??1),old.id]);else run('INSERT INTO reservation_slots(id,reservation_day_id,mark,starts_at,ends_at,capacity,status) VALUES(?,?,?,?,?,?,?)',[id(),dayId,slot.mark,slot.start,slot.end,capacity,Number(slot.status??1)]);}}
  const obsolete=all('SELECT s.id,s.mark FROM reservation_slots s JOIN reservation_days d ON d.id=s.reservation_day_id WHERE d.reservation_id=?',[recordId]).filter(s=>!retained.includes(s.mark));for(const slot of obsolete){if(!one('SELECT id FROM bookings WHERE slot_id=? LIMIT 1',[slot.id]))run('DELETE FROM reservation_slots WHERE id=?',[slot.id]);}
  run('DELETE FROM reservation_days WHERE reservation_id=? AND id NOT IN (SELECT DISTINCT reservation_day_id FROM reservation_slots)',[recordId]);return{id:recordId};
}

