  'reservation/list_has_day':({params})=>all("SELECT DISTINCT day FROM reservation_days WHERE project_id=? AND day>=? ORDER BY day",[PROJECT,must(params.day,'开始日期')]).map(r=>r.day),
  'reservation/list_by_day':({params})=>all("SELECT r.* FROM reservations r JOIN reservation_days d ON d.reservation_id=r.id WHERE r.project_id=? AND d.day=? AND r.status IN (1,9) ORDER BY r.sort_order",[PROJECT,params.day]),
  'reservation/view':({params})=>{const r=one('SELECT * FROM reservations WHERE id=? AND project_id=?',[params.id,PROJECT]);if(!r)throw new ApiError('预约项目不存在');return{_id:r.id,RESERVATION_TITLE:r.title,RESERVATION_CONTENT:json(r.content_json,[]),RESERVATION_STYLE_SET:json(r.style_json,{}),RESERVATION_FORM_SET:json(r.form_schema_json,[]),RESERVATION_STATUS:r.status};},
  'reservation/detail_for_join':({params,token})=>{const r=handlers['reservation/view']({params:{id:params.reservationId}}),slot=one('SELECT s.*,d.day FROM reservation_slots s JOIN reservation_days d ON d.id=s.reservation_day_id WHERE s.mark=? AND d.reservation_id=?',[params.timeMark,params.reservationId]);if(!slot)throw new ApiError('预约时段不存在');return{reservation:r,timeSet:{mark:slot.mark,start:slot.starts_at,end:slot.ends_at,limit:slot.capacity},day:slot.day,myForms:[]};},
  'reservation/before_join':()=>({allowed:true}),
  'reservation/join':({params,token})=>{const user=userFor(token),slot=one('SELECT s.*,d.day,d.reservation_id,r.title FROM reservation_slots s JOIN reservation_days d ON d.id=s.reservation_day_id JOIN reservations r ON r.id=d.reservation_id WHERE s.mark=? AND d.reservation_id=?',[params.timeMark,params.reservationId]);if(!slot)throw new ApiError('预约时段不存在');const bookingId=id(),code=Array.from(crypto.randomBytes(15),byte=>byte%10).join('');run('INSERT INTO bookings(id,project_id,reservation_id,slot_id,user_id,reservation_title,booking_day,starts_at,ends_at,starts_at_timestamp,verification_code,forms_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[bookingId,PROJECT,slot.reservation_id,slot.id,user.id,slot.title,slot.day,slot.starts_at,slot.ends_at,Math.floor(new Date(`${slot.day}T${slot.starts_at}:00+08:00`).getTime()/1000),code,JSON.stringify(params.forms||[])]);return{id:bookingId,code};},
  'reservation/my_join_list':({params,token})=>{const user=userFor(token),{page,size}=pageInput(params);const result=paginate('bookings','project_id=$project AND user_id=$user',{$project:PROJECT,$user:user.id},'created_at DESC',page,size);result.list=result.list.map(b=>({_id:b.id,BOOKING_RESERVATION_TITLE:b.reservation_title,BOOKING_RESERVATION_DAY:b.booking_day,BOOKING_RESERVATION_TIME_START:b.starts_at,BOOKING_RESERVATION_TIME_END:b.ends_at,BOOKING_STATUS:b.status,BOOKING_CODE:b.verification_code,BOOKING_IS_CHECKIN:b.checked_in,BOOKING_ADD_TIME:b.created_at}));return result;},
  'reservation/my_join_someday':({params,token})=>{const user=userFor(token,false);if(!user)return[];return all('SELECT * FROM bookings WHERE project_id=? AND user_id=? AND booking_day=? ORDER BY starts_at,created_at DESC',[PROJECT,user.id,must(params.day,'日期')]).map(bookingAdminRow);},
  'reservation/my_join_detail':({params,token})=>{const user=userFor(token),b=one('SELECT * FROM bookings WHERE id=? AND user_id=?',[params.joinId,user.id]);if(!b)throw new ApiError('预约记录不存在');return{_id:b.id,BOOKING_RESERVATION_TITLE:b.reservation_title,BOOKING_RESERVATION_DAY:b.booking_day,BOOKING_RESERVATION_TIME_START:b.starts_at,BOOKING_RESERVATION_TIME_END:b.ends_at,BOOKING_STATUS:b.status,BOOKING_CODE:b.verification_code,BOOKING_IS_CHECKIN:b.checked_in,BOOKING_FORMS:json(b.forms_json,[]),BOOKING_ADD_TIME:b.created_at};},
  'reservation/my_join_cancel':({params,token})=>{const user=userFor(token);const r=run('UPDATE bookings SET status=10,updated_at=unixepoch() WHERE id=? AND user_id=? AND status=1 AND checked_in=0',[params.joinId,user.id]);if(!r.changes)throw new ApiError('预约不可取消');return{cancelled:true};},
  'passport/login':({token})=>{const u=userFor(token);run('UPDATE users SET login_count=login_count+1,login_at=unixepoch(),updated_at=unixepoch() WHERE id=?',[u.id]);return{id:u.mini_openid,name:u.name,mobile:u.mobile,status:u.status};},
  'passport/phone':({params})=>{if(params.phone&&/^1[3-9]\d{9}$/.test(params.phone))return params.phone;throw new ApiError('本地模式无法解密微信手机号，请手动填写手机号',DATA);},
