  'passport/register':({params,token})=>{const u=userFor(token);run('UPDATE users SET name=?,mobile=?,forms_json=?,profile_json=?,status=?,updated_at=unixepoch() WHERE id=?',[must(params.name,'昵称'),must(params.mobile,'手机'),JSON.stringify(params.forms||[]),JSON.stringify(Object.fromEntries((params.forms||[]).map(f=>[f.mark,f.val]))),Number(params.status)||1,u.id]);return{id:u.mini_openid,name:params.name,mobile:params.mobile,status:Number(params.status)||1};},
