  'fav/update':({params,token})=>{const u=userFor(token),old=one('SELECT id FROM favorites WHERE user_id=? AND content_id=?',[u.id,params.oid]);if(old){run('DELETE FROM favorites WHERE id=?',[old.id]);return{isFav:0};}run('INSERT INTO favorites(id,project_id,user_id,content_type,content_id,title,path) VALUES(?,?,?,?,?,?,?)',[id(),PROJECT,u.id,params.type,params.oid,params.title,params.path]);return{isFav:1};},
