  'fav/my_list':({params,token})=>{const u=userFor(token),{page,size}=pageInput(params);const r=paginate('favorites','project_id=$project AND user_id=$user',{$project:PROJECT,$user:u.id},'created_at DESC',page,size);r.list=r.list.map(f=>({_id:f.id,FAV_TITLE:f.title,FAV_TYPE:f.content_type,FAV_OID:f.content_id,FAV_PATH:f.path,FAV_ADD_TIME:f.created_at}));return r;},
  'feedback/submit':({params,token})=>{const u=userFor(token),existing=one('SELECT id,status FROM feedback WHERE project_id=? AND user_id=? AND request_key=?',[PROJECT,u.id,params.requestId]);if(existing)return{id:existing.id,status:existing.status};const fid=id();run('INSERT INTO feedback(id,project_id,user_id,category,content,phone,images_json,request_key) VALUES(?,?,?,?,?,?,?,?)',[fid,PROJECT,u.id,must(params.category,'反馈类型'),must(params.content,'反馈内容'),params.phone||'',JSON.stringify(params.images||[]),params.requestId]);return{id:fid,status:0};},
  'feedback/upload':({params,token})=>{const user=userFor(token),requestId=must(params.requestId,'请求编号'),fileID=saveBase64(`feedback/${user.id}/${requestId}`,params.base64);registerAsset({module:'feedback',recordId:requestId,fileID,base64:params.base64,userId:user.id});return{fileID};},
  'feedback/my_list':({params,token})=>{const u=userFor(token),{page,size}=pageInput(params);const r=paginate('feedback','project_id=$project AND user_id=$user',{$project:PROJECT,$user:u.id},'created_at DESC',page,size);r.list=r.list.map(f=>({_id:f.id,FEEDBACK_CATEGORY:f.category,FEEDBACK_CONTENT:f.content,FEEDBACK_IMAGES:json(f.images_json,[]),FEEDBACK_STATUS:f.status,FEEDBACK_REPLY:f.reply,FEEDBACK_ADD_TIME:f.created_at}));return r;},
  'admin/login':({params})=>{const a=one('SELECT * FROM admins WHERE project_id=? AND name=? AND status=1 AND deleted=0',[PROJECT,params.name]);if(!a)throw new ApiError('账号或密码错误',ADMIN);const [type,salt,hash]=a.password_hash.split('$');if(type!=='scrypt'||crypto.scryptSync(params.pwd||'',salt,32).toString('hex')!==hash)throw new ApiError('账号或密码错误',ADMIN);const token=crypto.randomBytes(24).toString('hex');run('UPDATE admins SET token=?,token_expires_at=?,login_count=login_count+1,login_at=unixepoch() WHERE id=?',[token,now()+7200,a.id]);return{id:a.id,name:a.name,desc:a.description,type:a.role,permissions:json(a.permissions_json,{}),token};},
