  'admin/cms_state':({params,token})=>{requireAdmin(token);if(params.module==='category'){run(`UPDATE content_categories SET state=?,published_at=CASE WHEN ?='published' THEN unixepoch() ELSE published_at END,updated_at=unixepoch() WHERE id=? AND project_id=?`,[params.state,params.state,params.id,PROJECT]);return{id:params.id,state:params.state};}if(params.module==='merchant'){const row=merchantRecord(params.id);if(!row)throw new ApiError('内容不存在');run(`UPDATE ${merchantTables[row.category]} SET state=?,published_at=CASE WHEN ?='published' THEN unixepoch() ELSE published_at END,updated_at=unixepoch() WHERE id=? AND project_id=?`,[params.state,params.state,params.id,PROJECT]);return{id:params.id,state:params.state};}const meta=modules[params.module];if(!meta)throw new ApiError('内容模块不正确');const statusSql=['spot','guide','news'].includes(params.module)?',status=?':'';const values=statusSql?[params.state,params.state==='published'?1:0,params.state,params.id,PROJECT]:[params.state,params.state,params.id,PROJECT];run(`UPDATE ${meta.table} SET ${meta.state}=?${statusSql},published_at=CASE WHEN ?='published' THEN unixepoch() ELSE published_at END,updated_at=unixepoch() WHERE id=? AND project_id=?`,values);return{id:params.id,state:params.state};},
