  'admin/user_data_export':({token})=>{requireAdmin(token);const rows=all('SELECT * FROM users WHERE project_id=? ORDER BY created_at DESC',[PROJECT]);saveCsv('user-data.csv',['用户ID','微信标识','昵称','手机号','状态','注册时间','资料'],rows.map(row=>[row.id,row.mini_openid,row.name,row.mobile,row.status,row.created_at,row.forms_json]));return{total:rows.length};},
